const { chromium } = require("playwright");
const path = require("path");
const [url, dst] = process.argv.slice(2);
(async () => {
  const browser = await chromium.launch(process.env.LW_CHROME ? { executablePath: process.env.LW_CHROME } : {});
  let ok = true;
  for (const w of [390, 1440]) {
    const ctx = await browser.newContext({ viewport: { width: w, height: w === 390 ? 844 : 900 } });
    const page = await ctx.newPage();
    const bad = [];
    page.on("console", (m) => { if (m.type() === "error" || /Content Security Policy|Refused to/i.test(m.text())) bad.push("console: " + m.text()); });
    page.on("pageerror", (e) => bad.push("pageerror: " + e.message));
    page.on("requestfailed", (r) => bad.push("failed: " + r.url()));
    page.on("response", (r) => { if (r.status() >= 400) bad.push(`http ${r.status()} ${r.url()}`); });
    await page.goto(url, { waitUntil: "networkidle" });
    await page.evaluate(() => document.fonts.ready);
    await page.screenshot({ path: path.join(dst, `live-${w}-top.png`) });
    const info = await page.evaluate(() => {
